import 'package:flutter/material.dart';
import 'package:video_player/video_player.dart';

class BasicVideoScreen extends StatefulWidget {
  const BasicVideoScreen({super.key});

  @override
  State<BasicVideoScreen> createState() => _BasicVideoScreenState();
}

class _BasicVideoScreenState extends State<BasicVideoScreen> {
  // 비디오 컨트롤러 선언
  late VideoPlayerController _controller;
  bool _isInitialized = false;

  @override
  void initState() {
    super.initState();
    _initializeVideo();
  }

  Future<void> _initializeVideo() async {
    // 네트워크 비디오로 컨트롤러 생성
    _controller = VideoPlayerController.networkUrl(
      Uri.parse('https://flutter.github.io/assets-for-api-docs/assets/videos/bee.mp4'),
    );

    try {
      // 비디오 초기화 (필수!)
      await _controller.initialize();

      // 상태 업데이트
      setState(() {
        _isInitialized = true;
      });

      // 자동 재생 (선택)
      // await _controller.play();
    } catch (e) {
      debugPrint('비디오 초기화 실패: $e');
    }
  }

  @override
  void dispose() {
    // 중요: 리소스 해제
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('기본 비디오 재생')),
      body: Center(
        child: _isInitialized
            ? Column(
                mainAxisAlignment: MainAxisAlignment.center,
                children: [
                  // 비디오 비율에 맞게 표시
                  AspectRatio(
                    aspectRatio: _controller.value.aspectRatio,
                    child: VideoPlayer(_controller),
                  ),
                  const SizedBox(height: 20),
                  // 재생/일시정지 버튼
                  ElevatedButton.icon(
                    onPressed: () {
                      setState(() {
                        if (_controller.value.isPlaying) {
                          _controller.pause();
                        } else {
                          _controller.play();
                        }
                      });
                    },
                    icon: Icon(
                      _controller.value.isPlaying
                          ? Icons.pause
                          : Icons.play_arrow,
                    ),
                    label: Text(
                      _controller.value.isPlaying ? '일시정지' : '재생',
                    ),
                  ),
                ],
              )
            : const CircularProgressIndicator(),
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:video_player/video_player.dart';

class VideoWithControls extends StatefulWidget {
  final String videoUrl;
  const VideoWithControls({super.key, required this.videoUrl});

  @override
  State<VideoWithControls> createState() => _VideoWithControlsState();
}

class _VideoWithControlsState extends State<VideoWithControls> {
  late VideoPlayerController _controller;
  bool _isInitialized = false;
  bool _showControls = true;

  @override
  void initState() {
    super.initState();
    _initVideo();
  }

  Future<void> _initVideo() async {
    _controller = VideoPlayerController.networkUrl(Uri.parse(widget.videoUrl));

    // 상태 변경 리스너 추가
    _controller.addListener(_videoListener);

    await _controller.initialize();
    setState(() => _isInitialized = true);
  }

  void _videoListener() {
    // 상태 변경 시 UI 업데이트
    if (mounted) setState(() {});
  }

  @override
  void dispose() {
    _controller.removeListener(_videoListener);
    _controller.dispose();
    super.dispose();
  }

  // 시간 포맷팅 (mm:ss)
  String _formatDuration(Duration duration) {
    String twoDigits(int n) => n.toString().padLeft(2, '0');
    final minutes = twoDigits(duration.inMinutes.remainder(60));
    final seconds = twoDigits(duration.inSeconds.remainder(60));
    return '$minutes:$seconds';
  }

  @override
  Widget build(BuildContext context) {
    if (!_isInitialized) {
      return const AspectRatio(
        aspectRatio: 16 / 9,
        child: Center(child: CircularProgressIndicator()),
      );
    }

    return AspectRatio(
      aspectRatio: _controller.value.aspectRatio,
      child: GestureDetector(
        onTap: () => setState(() => _showControls = !_showControls),
        child: Stack(
          alignment: Alignment.center,
          children: [
            // 비디오 화면
            VideoPlayer(_controller),

            // 버퍼링 인디케이터
            if (_controller.value.isBuffering)
              const CircularProgressIndicator(color: Colors.white),

            // 컨트롤 오버레이
            if (_showControls)
              Container(
                color: Colors.black38,
                child: Column(
                  mainAxisAlignment: MainAxisAlignment.end,
                  children: [
                    // 중앙 재생 버튼
                    Expanded(
                      child: Center(
                        child: IconButton(
                          iconSize: 64,
                          color: Colors.white,
                          icon: Icon(
                            _controller.value.isPlaying
                                ? Icons.pause_circle
                                : Icons.play_circle,
                          ),
                          onPressed: () {
                            _controller.value.isPlaying
                                ? _controller.pause()
                                : _controller.play();
                          },
                        ),
                      ),
                    ),

                    // 하단 컨트롤 바
                    _buildBottomControls(),
                  ],
                ),
              ),
          ],
        ),
      ),
    );
  }

  Widget _buildBottomControls() {
    final position = _controller.value.position;
    final duration = _controller.value.duration;

    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 8),
      child: Row(
        children: [
          // 현재 시간
          Text(
            _formatDuration(position),
            style: const TextStyle(color: Colors.white),
          ),

          // 진행 바
          Expanded(
            child: Slider(
              value: position.inMilliseconds.toDouble(),
              min: 0,
              max: duration.inMilliseconds.toDouble(),
              onChanged: (value) {
                _controller.seekTo(Duration(milliseconds: value.toInt()));
              },
            ),
          ),

          // 전체 시간
          Text(
            _formatDuration(duration),
            style: const TextStyle(color: Colors.white),
          ),

          // 전체화면 버튼
          IconButton(
            icon: const Icon(Icons.fullscreen, color: Colors.white),
            onPressed: () {
              // 전체화면 로직 구현
            },
          ),
        ],
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:video_player/video_player.dart';

class VideoSettingsExample extends StatefulWidget {
  const VideoSettingsExample({super.key});

  @override
  State<VideoSettingsExample> createState() => _VideoSettingsExampleState();
}

class _VideoSettingsExampleState extends State<VideoSettingsExample> {
  late VideoPlayerController _controller;
  double _volume = 1.0;
  double _playbackSpeed = 1.0;
  bool _isInitialized = false;

  final List<double> _speedOptions = [0.5, 0.75, 1.0, 1.25, 1.5, 2.0];

  @override
  void initState() {
    super.initState();
    _initVideo();
  }

  Future<void> _initVideo() async {
    _controller = VideoPlayerController.networkUrl(
      Uri.parse('https://flutter.github.io/assets-for-api-docs/assets/videos/bee.mp4'),
    );
    await _controller.initialize();
    await _controller.setLooping(true);  // 반복 재생
    setState(() => _isInitialized = true);
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    if (!_isInitialized) {
      return const Center(child: CircularProgressIndicator());
    }

    return Column(
      children: [
        // 비디오 플레이어
        AspectRatio(
          aspectRatio: _controller.value.aspectRatio,
          child: VideoPlayer(_controller),
        ),

        const SizedBox(height: 16),

        // 기본 진행 바
        VideoProgressIndicator(
          _controller,
          allowScrubbing: true,  // 터치로 탐색 허용
          padding: const EdgeInsets.symmetric(horizontal: 16),
        ),

        const SizedBox(height: 16),

        // 재생 컨트롤
        Row(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            // 10초 뒤로
            IconButton(
              icon: const Icon(Icons.replay_10),
              onPressed: () {
                final newPosition = _controller.value.position - 
                    const Duration(seconds: 10);
                _controller.seekTo(newPosition);
              },
            ),

            // 재생/일시정지
            IconButton(
              iconSize: 48,
              icon: Icon(
                _controller.value.isPlaying ? Icons.pause : Icons.play_arrow,
              ),
              onPressed: () {
                setState(() {
                  _controller.value.isPlaying
                      ? _controller.pause()
                      : _controller.play();
                });
              },
            ),

            // 10초 앞으로
            IconButton(
              icon: const Icon(Icons.forward_10),
              onPressed: () {
                final newPosition = _controller.value.position + 
                    const Duration(seconds: 10);
                _controller.seekTo(newPosition);
              },
            ),
          ],
        ),

        const Divider(),

        // 볼륨 조절
        Padding(
          padding: const EdgeInsets.symmetric(horizontal: 16),
          child: Row(
            children: [
              Icon(_volume == 0 ? Icons.volume_off : Icons.volume_up),
              Expanded(
                child: Slider(
                  value: _volume,
                  min: 0,
                  max: 1,
                  onChanged: (value) {
                    setState(() => _volume = value);
                    _controller.setVolume(value);
                  },
                ),
              ),
              Text('${(_volume * 100).toInt()}%'),
            ],
          ),
        ),

        // 재생 속도
        Padding(
          padding: const EdgeInsets.symmetric(horizontal: 16),
          child: Row(
            children: [
              const Icon(Icons.speed),
              const SizedBox(width: 16),
              const Text('재생 속도: '),
              DropdownButton<double>(
                value: _playbackSpeed,
                items: _speedOptions.map((speed) {
                  return DropdownMenuItem(
                    value: speed,
                    child: Text('${speed}x'),
                  );
                }).toList(),
                onChanged: (value) {
                  if (value != null) {
                    setState(() => _playbackSpeed = value);
                    _controller.setPlaybackSpeed(value);
                  }
                },
              ),
            ],
          ),
        ),

        // 음소거/반복 토글
        Row(
          mainAxisAlignment: MainAxisAlignment.spaceEvenly,
          children: [
            TextButton.icon(
              icon: Icon(_volume == 0 ? Icons.volume_off : Icons.volume_up),
              label: const Text('음소거'),
              onPressed: () {
                setState(() {
                  _volume = _volume == 0 ? 1.0 : 0;
                  _controller.setVolume(_volume);
                });
              },
            ),
            TextButton.icon(
              icon: Icon(
                _controller.value.isLooping ? Icons.repeat_one : Icons.repeat,
              ),
              label: Text(_controller.value.isLooping ? '반복 ON' : '반복 OFF'),
              onPressed: () {
                _controller.setLooping(!_controller.value.isLooping);
                setState(() {});
              },
            ),
          ],
        ),
      ],
    );
  }
}

import 'dart:io';
import 'package:flutter/material.dart';
