class VideoService {
  // 네트워크 URL 비디오
  static VideoPlayerController fromNetwork(String url) {
    return VideoPlayerController.networkUrl(
      Uri.parse(url),
      // HTTP 헤더 설정 (인증 등)
      httpHeaders: {
        'Authorization': 'Bearer token',
      },
    );
  }

  // 로컬 파일 비디오
  static VideoPlayerController fromFile(File file) {
    return VideoPlayerController.file(file);
  }

  // Assets 비디오
  static VideoPlayerController fromAsset(String assetPath) {
    return VideoPlayerController.asset(assetPath);
  }
}

