// 여러 비디오 관리 (재생목록)
class VideoPlaylist extends StatefulWidget {
  final List<String> videoUrls;
  const VideoPlaylist({super.key, required this.videoUrls});

  @override
  State<VideoPlaylist> createState() => _VideoPlaylistState();
}

class _VideoPlaylistState extends State<VideoPlaylist> {
  late VideoPlayerController _controller;
  int _currentIndex = 0;

  @override
  void initState() {
    super.initState();
    _initVideo(_currentIndex);
  }

  Future<void> _initVideo(int index) async {
    // 이전 컨트롤러 해제
    if (_currentIndex != index) {
      await _controller.dispose();
    }

    _controller = VideoPlayerController.networkUrl(
      Uri.parse(widget.videoUrls[index]),
    );

    await _controller.initialize();

    // 재생 완료 시 다음 비디오로
    _controller.addListener(() {
      if (_controller.value.position >= _controller.value.duration) {
        _playNext();
      }
    });

    setState(() => _currentIndex = index);
    _controller.play();
  }

  void _playNext() {
    if (_currentIndex < widget.videoUrls.length - 1) {
      _initVideo(_currentIndex + 1);
    }
  }

  void _playPrevious() {
    if (_currentIndex > 0) {
      _initVideo(_currentIndex - 1);
    }
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Column(
      children: [
        if (_controller.value.isInitialized)
          AspectRatio(
            aspectRatio: _controller.value.aspectRatio,
            child: VideoPlayer(_controller),
          ),
        Row(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            IconButton(
              icon: const Icon(Icons.skip_previous),
              onPressed: _currentIndex > 0 ? _playPrevious : null,
            ),
            Text('${_currentIndex + 1} / ${widget.videoUrls.length}'),
            IconButton(
              icon: const Icon(Icons.skip_next),
              onPressed: _currentIndex < widget.videoUrls.length - 1
                  ? _playNext
                  : null,
            ),
          ],
        ),
      ],
    );
  }
}

